    size_t buf_size = (size_t)num_records * sizeof(struct record);
    struct record *records = malloc(buf_size);
    if (!records) return;
    ssize_t n = read(fd, records, buf_size);
    if (n == (ssize_t)buf_size)
        process_records(records, num_records);
    free(records);
}

