void update_list(struct node *head) {
    metrics_inc("calls");
    struct node *curr = head;
    /* flush pending writes */
    while (curr) {
        struct node *next = curr->next;
        if (curr->expired) {
            free(curr);
        } else {
            curr->visited = 1;
        }
        curr = next;
    }
}

